\n  static get singleRegex() {\n    return /^(.*)\\$$/\n  }\n  search(text) {\n    const isMatch = text.endsWith(this.pattern);\n\n    return {\n      isMatch,\n      score: isMatch ? 0 : 1,\n      indices: [text.length - this.pattern.length, text.length - 1]\n    }\n  }\n}\n\n// Token: !.file$\n\nclass InverseSuffixExactMatch extends BaseMatch {\n  constructor(pattern) {\n    super(pattern);\n  }\n  static get type() {\n    return 'inverse-suffix-exact'\n  }\n  static get multiRegex() {\n    return /^!\"(.*)\"\\$$/\n  }\n  static get singleRegex() {\n    return /^!(.*)\\$$/\n  }\n  search(text) {\n    const isMatch = !text.endsWith(this.pattern);\n    return {\n      isMatch,\n      score: isMatch ? 0 : 1,\n      indices: [0, text.length - 1]\n    }\n  }\n}\n\nclass FuzzyMatch extends BaseMatch {\n  constructor(\n    pattern,\n    {\n      location = Config.location,\n      threshold = Config.threshold,\n      distance = Config.distance,\n      includeMatches = Config.includeMatches,\n      findAllMatches = Config.findAllMatches,\n      minMatchCharLength = Config.minMatchCharLength,\n      isCaseSensitive = Config.isCaseSensitive,\n      ignoreDiacritics = Config.ignoreDiacritics,\n      ignoreLocation = Config.ignoreLocation\n    } = {}\n  ) {\n    super(pattern);\n    this._bitapSearch = new BitapSearch(pattern, {\n      location,\n      threshold,\n      distance,\n      includeMatches,\n      findAllMatches,\n      minMatchCharLength,\n      isCaseSensitive,\n      ignoreDiacritics,\n      ignoreLocation\n    });\n  }\n  static get type() {\n    return 'fuzzy'\n  }\n  static get multiRegex() {\n    return /^\"(.*)\"$/\n  }\n  static get singleRegex() {\n    return /^(.*)$/\n  }\n  search(text) {\n    return this._bitapSearch.searchIn(text)\n  }\n}\n\n// Token: 'file\n\nclass IncludeMatch extends BaseMatch {\n  constructor(pattern) {\n    super(pattern);\n  }\n  static get type() {\n    return 'include'\n  }\n  static get multiRegex() {\n    return /^'\"(.*)\"$/\n  }\n  static get singleRegex() {\n    return /^'(.*)$/\n  }\n  search(text) {\n    let location = 0;\n    let index;\n\n    const indices = [];\n    const patternLen = this.pattern.length;\n\n    // Get all exact matches\n    while ((index = text.indexOf(this.pattern, location)) > -1) {\n      location = index + patternLen;\n      indices.push([index, location - 1]);\n    }\n\n    const isMatch = !!indices.length;\n\n    return {\n      isMatch,\n      score: isMatch ? 0 : 1,\n      indices\n    }\n  }\n}\n\n// ❗Order is important. DO NOT CHANGE.\nconst searchers = [\n  ExactMatch,\n  IncludeMatch,\n  PrefixExactMatch,\n  InversePrefixExactMatch,\n  InverseSuffixExactMatch,\n  SuffixExactMatch,\n  InverseExactMatch,\n  FuzzyMatch\n];\n\nconst searchersLen = searchers.length;\n\n// Regex to split by spaces, but keep anything in quotes together\nconst SPACE_RE = / +(?=(?:[^\\\"]*\\\"[^\\\"]*\\\")*[^\\\"]*$)/;\nconst OR_TOKEN = '|';\n\n// Return a 2D array representation of the query, for simpler parsing.\n// Example:\n// \"^core go$ | rb$ | py$ xy$\" => [[\"^core\", \"go$\"], [\"rb$\"], [\"py$\", \"xy$\"]]\nfunction parseQuery(pattern, options = {}) {\n  return pattern.split(OR_TOKEN).map((item) => {\n    let query = item\n      .trim()\n      .split(SPACE_RE)\n      .filter((item) => item && !!item.trim());\n\n    let results = [];\n    for (let i = 0, len = query.length; i < len; i += 1) {\n      const queryItem = query[i];\n\n      // 1. Handle multiple query match (i.e, once that are quoted, like `\"hello world\"`)\n      let found = false;\n      let idx = -1;\n      while (!found && ++idx < searchersLen) {\n        const searcher = searchers[idx];\n        let token = searcher.isMultiMatch(queryItem);\n        if (token) {\n          results.push(new searcher(token, options));\n          found = true;\n        }\n      }\n\n      if (found) {\n        continue\n      }\n\n      // 2. Handle single query matches (i.e, once that are *not* quoted)\n      idx = -1;\n      while (++idx < searchersLen) {\n        const searcher = searchers[idx];\n        let token = searcher.isSingleMatch(queryItem);\n        if (token) {\n          results.push(new searcher(token, options));\n          break\n        }\n      }\n    }\n\n    return results\n  })\n}\n\n// These extended matchers can return an array of matches, as opposed\n// to a singl match\nconst MultiMatchSet = new Set([FuzzyMatch.type, IncludeMatch.type]);\n\n/**\n * Command-like searching\n * ======================\n *\n * Given multiple search terms delimited by spaces.e.g. `^jscript .python$ ruby !java`,\n * search in a given text.\n *\n * Search syntax:\n *\n * | Token       | Match type                 | Description                            |\n * | ----------- | -------------------------- | -------------------------------------- |\n * | `jscript`   | fuzzy-match                | Items that fuzzy match `jscript`       |\n * | `=scheme`   | exact-match                | Items that are `scheme`                |\n * | `'python`   | include-match              | Items that include `python`            |\n * | `!ruby`     | inverse-exact-match        | Items that do not include `ruby`       |\n * | `^java`     | prefix-exact-match         | Items that start with `java`           |\n * | `!^earlang` | inverse-prefix-exact-match | Items that do not start with `earlang` |\n * | `.js$`      | suffix-exact-match         | Items that end with `.js`              |\n * | `!.go$`     | inverse-suffix-exact-match | Items that do not end with `.go`       |\n *\n * A single pipe character acts as an OR operator. For example, the following\n * query matches entries that start with `core` and end with either`go`, `rb`,\n * or`py`.\n *\n * ```\n * ^core go$ | rb$ | py$\n * ```\n */\nclass ExtendedSearch {\n  constructor(\n    pattern,\n    {\n      isCaseSensitive = Config.isCaseSensitive,\n      ignoreDiacritics = Config.ignoreDiacritics,\n      includeMatches = Config.includeMatches,\n      minMatchCharLength = Config.minMatchCharLength,\n      ignoreLocation = Config.ignoreLocation,\n      findAllMatches = Config.findAllMatches,\n      location = Config.location,\n      threshold = Config.threshold,\n      distance = Config.distance\n    } = {}\n  ) {\n    this.query = null;\n    this.options = {\n      isCaseSensitive,\n      ignoreDiacritics,\n      includeMatches,\n      minMatchCharLength,\n      findAllMatches,\n      ignoreLocation,\n      location,\n      threshold,\n      distance\n    };\n\n    pattern = isCaseSensitive ? pattern : pattern.toLowerCase();\n    pattern = ignoreDiacritics ? stripDiacritics(pattern) : pattern;\n    this.pattern = pattern;\n    this.query = parseQuery(this.pattern, this.options);\n  }\n\n  static condition(_, options) {\n    return options.useExtendedSearch\n  }\n\n  searchIn(text) {\n    const query = this.query;\n\n    if (!query) {\n      return {\n        isMatch: false,\n        score: 1\n      }\n    }\n\n    const { includeMatches, isCaseSensitive, ignoreDiacritics } = this.options;\n\n    text = isCaseSensitive ? text : text.toLowerCase();\n    text = ignoreDiacritics ? stripDiacritics(text) : text;\n\n    let numMatches = 0;\n    let allIndices = [];\n    let totalScore = 0;\n\n    // ORs\n    for (let i = 0, qLen = query.length; i < qLen; i += 1) {\n      const searchers = query[i];\n\n      // Reset indices\n      allIndices.length = 0;\n      numMatches = 0;\n\n      // ANDs\n      for (let j = 0, pLen = searchers.length; j < pLen; j += 1) {\n        const searcher = searchers[j];\n        const { isMatch, indices, score } = searcher.search(text);\n\n        if (isMatch) {\n          numMatches += 1;\n          totalScore += score;\n          if (includeMatches) {\n            const type = searcher.constructor.type;\n            if (MultiMatchSet.has(type)) {\n              allIndices = [...allIndices, ...indices];\n            } else {\n              allIndices.push(indices);\n            }\n          }\n        } else {\n          totalScore = 0;\n          numMatches = 0;\n          allIndices.length = 0;\n          break\n        }\n      }\n\n      // OR condition, so if TRUE, return\n      if (numMatches) {\n        let result = {\n          isMatch: true,\n          score: totalScore / numMatches\n        };\n\n        if (includeMatches) {\n          result.indices = allIndices;\n        }\n\n        return result\n      }\n    }\n\n    // Nothing was matched\n    return {\n      isMatch: false,\n      score: 1\n    }\n  }\n}\n\nconst registeredSearchers = [];\n\nfunction register(...args) {\n  registeredSearchers.push(...args);\n}\n\nfunction createSearcher(pattern, options) {\n  for (let i = 0, len = registeredSearchers.length; i < len; i += 1) {\n    let searcherClass = registeredSearchers[i];\n    if (searcherClass.condition(pattern, options)) {\n      return new searcherClass(pattern, options)\n    }\n  }\n\n  return new BitapSearch(pattern, options)\n}\n\nconst LogicalOperator = {\n  AND: '$and',\n  OR: '$or'\n};\n\nconst KeyType = {\n  PATH: '$path',\n  PATTERN: '$val'\n};\n\nconst isExpression = (query) =>\n  !!(query[LogicalOperator.AND] || query[LogicalOperator.OR]);\n\nconst isPath = (query) => !!query[KeyType.PATH];\n\nconst isLeaf = (query) =>\n  !isArray(query) && isObject(query) && !isExpression(query);\n\nconst convertToExplicit = (query) => ({\n  [LogicalOperator.AND]: Object.keys(query).map((key) => ({\n    [key]: query[key]\n  }))\n});\n\n// When `auto` is `true`, the parse function will infer and initialize and add\n// the appropriate `Searcher` instance\nfunction parse(query, options, { auto = true } = {}) {\n  const next = (query) => {\n    let keys = Object.keys(query);\n\n    const isQueryPath = isPath(query);\n\n    if (!isQueryPath && keys.length > 1 && !isExpression(query)) {\n      return next(convertToExplicit(query))\n    }\n\n    if (isLeaf(query)) {\n      const key = isQueryPath ? query[KeyType.PATH] : keys[0];\n\n      const pattern = isQueryPath ? query[KeyType.PATTERN] : query[key];\n\n      if (!isString(pattern)) {\n        throw new Error(LOGICAL_SEARCH_INVALID_QUERY_FOR_KEY(key))\n      }\n\n      const obj = {\n        keyId: createKeyId(key),\n        pattern\n      };\n\n      if (auto) {\n        obj.searcher = createSearcher(pattern, options);\n      }\n\n      return obj\n    }\n\n    let node = {\n      children: [],\n      operator: keys[0]\n    };\n\n    keys.forEach((key) => {\n      const value = query[key];\n\n      if (isArray(value)) {\n        value.forEach((item) => {\n          node.children.push(next(item));\n        });\n      }\n    });\n\n    return node\n  };\n\n  if (!isExpression(query)) {\n    query = convertToExplicit(query);\n  }\n\n  return next(query)\n}\n\n// Practical scoring function\nfunction computeScore(\n  results,\n  { ignoreFieldNorm = Config.ignoreFieldNorm }\n) {\n  results.forEach((result) => {\n    let totalScore = 1;\n\n    result.matches.forEach(({ key, norm, score }) => {\n      const weight = key ? key.weight : null;\n\n      totalScore *= Math.pow(\n        score === 0 && weight ? Number.EPSILON : score,\n        (weight || 1) * (ignoreFieldNorm ? 1 : norm)\n      );\n    });\n\n    result.score = totalScore;\n  });\n}\n\nfunction transformMatches(result, data) {\n  const matches = result.matches;\n  data.matches = [];\n\n  if (!isDefined(matches)) {\n    return\n  }\n\n  matches.forEach((match) => {\n    if (!isDefined(match.indices) || !match.indices.length) {\n      return\n    }\n\n    const { indices, value } = match;\n\n    let obj = {\n      indices,\n      value\n    };\n\n    if (match.key) {\n      obj.key = match.key.src;\n    }\n\n    if (match.idx > -1) {\n      obj.refIndex = match.idx;\n    }\n\n    data.matches.push(obj);\n  });\n}\n\nfunction transformScore(result, data) {\n  data.score = result.score;\n}\n\nfunction format(\n  results,\n  docs,\n  {\n    includeMatches = Config.includeMatches,\n    includeScore = Config.includeScore\n  } = {}\n) {\n  const transformers = [];\n\n  if (includeMatches) transformers.push(transformMatches);\n  if (includeScore) transformers.push(transformScore);\n\n  return results.map((result) => {\n    const { idx } = result;\n\n    const data = {\n      item: docs[idx],\n      refIndex: idx\n    };\n\n    if (transformers.length) {\n      transformers.forEach((transformer) => {\n        transformer(result, data);\n      });\n    }\n\n    return data\n  })\n}\n\nclass Fuse {\n  constructor(docs, options = {}, index) {\n    this.options = { ...Config, ...options };\n\n    if (\n      this.options.useExtendedSearch &&\n      !true\n    ) {\n      throw new Error(EXTENDED_SEARCH_UNAVAILABLE)\n    }\n\n    this._keyStore = new KeyStore(this.options.keys);\n\n    this.setCollection(docs, index);\n  }\n\n  setCollection(docs, index) {\n    this._docs = docs;\n\n    if (index && !(index instanceof FuseIndex)) {\n      throw new Error(INCORRECT_INDEX_TYPE)\n    }\n\n    this._myIndex =\n      index ||\n      createIndex(this.options.keys, this._docs, {\n        getFn: this.options.getFn,\n        fieldNormWeight: this.options.fieldNormWeight\n      });\n  }\n\n  add(doc) {\n    if (!isDefined(doc)) {\n      return\n    }\n\n    this._docs.push(doc);\n    this._myIndex.add(doc);\n  }\n\n  remove(predicate = (/* doc, idx */) => false) {\n    const results = [];\n\n    for (let i = 0, len = this._docs.length; i < len; i += 1) {\n      const doc = this._docs[i];\n      if (predicate(doc, i)) {\n        this.removeAt(i);\n        i -= 1;\n        len -= 1;\n\n        results.push(doc);\n      }\n    }\n\n    return results\n  }\n\n  removeAt(idx) {\n    this._docs.splice(idx, 1);\n    this._myIndex.removeAt(idx);\n  }\n\n  getIndex() {\n    return this._myIndex\n  }\n\n  search(query, { limit = -1 } = {}) {\n    const {\n      includeMatches,\n      includeScore,\n      shouldSort,\n      sortFn,\n      ignoreFieldNorm\n    } = this.options;\n\n    let results = isString(query)\n      ? isString(this._docs[0])\n        ? this._searchStringList(query)\n        : this._searchObjectList(query)\n      : this._searchLogical(query);\n\n    computeScore(results, { ignoreFieldNorm });\n\n    if (shouldSort) {\n      results.sort(sortFn);\n    }\n\n    if (isNumber(limit) && limit > -1) {\n      results = results.slice(0, limit);\n    }\n\n    return format(results, this._docs, {\n      includeMatches,\n      includeScore\n    })\n  }\n\n  _searchStringList(query) {\n    const searcher = createSearcher(query, this.options);\n    const { records } = this._myIndex;\n    const results = [];\n\n    // Iterate over every string in the index\n    records.forEach(({ v: text, i: idx, n: norm }) => {\n      if (!isDefined(text)) {\n        return\n      }\n\n      const { isMatch, score, indices } = searcher.searchIn(text);\n\n      if (isMatch) {\n        results.push({\n          item: text,\n          idx,\n          matches: [{ score, value: text, norm, indices }]\n        });\n      }\n    });\n\n    return results\n  }\n\n  _searchLogical(query) {\n\n    const expression = parse(query, this.options);\n\n    const evaluate = (node, item, idx) => {\n      if (!node.children) {\n        const { keyId, searcher } = node;\n\n        const matches = this._findMatches({\n          key: this._keyStore.get(keyId),\n          value: this._myIndex.getValueForItemAtKeyId(item, keyId),\n          searcher\n        });\n\n        if (matches && matches.length) {\n          return [\n            {\n              idx,\n              item,\n              matches\n            }\n          ]\n        }\n\n        return []\n      }\n\n      const res = [];\n      for (let i = 0, len = node.children.length; i < len; i += 1) {\n        const child = node.children[i];\n        const result = evaluate(child, item, idx);\n        if (result.length) {\n          res.push(...result);\n        } else if (node.operator === LogicalOperator.AND) {\n          return []\n        }\n      }\n      return res\n    };\n\n    const records = this._myIndex.records;\n    const resultMap = {};\n    const results = [];\n\n    records.forEach(({ $: item, i: idx }) => {\n      if (isDefined(item)) {\n        let expResults = evaluate(expression, item, idx);\n\n        if (expResults.length) {\n          // Dedupe when adding\n          if (!resultMap[idx]) {\n            resultMap[idx] = { idx, item, matches: [] };\n            results.push(resultMap[idx]);\n          }\n          expResults.forEach(({ matches }) => {\n            resultMap[idx].matches.push(...matches);\n          });\n        }\n      }\n    });\n\n    return results\n  }\n\n  _searchObjectList(query) {\n    const searcher = createSearcher(query, this.options);\n    const { keys, records } = this._myIndex;\n    const results = [];\n\n    // List is Array<Object>\n    records.forEach(({ $: item, i: idx }) => {\n      if (!isDefined(item)) {\n        return\n      }\n\n      let matches = [];\n\n      // Iterate over every key (i.e, path), and fetch the value at that key\n      keys.forEach((key, keyIndex) => {\n        matches.push(\n          ...this._findMatches({\n            key,\n            value: item[keyIndex],\n            searcher\n          })\n        );\n      });\n\n      if (matches.length) {\n        results.push({\n          idx,\n          item,\n          matches\n        });\n      }\n    });\n\n    return results\n  }\n  _findMatches({ key, value, searcher }) {\n    if (!isDefined(value)) {\n      return []\n    }\n\n    let matches = [];\n\n    if (isArray(value)) {\n      value.forEach(({ v: text, i: idx, n: norm }) => {\n        if (!isDefined(text)) {\n          return\n        }\n\n        const { isMatch, score, indices } = searcher.searchIn(text);\n\n        if (isMatch) {\n          matches.push({\n            score,\n            key,\n            value: text,\n            idx,\n            norm,\n            indices\n          });\n        }\n      });\n    } else {\n      const { v: text, n: norm } = value;\n\n      const { isMatch, score, indices } = searcher.searchIn(text);\n\n      if (isMatch) {\n        matches.push({ score, key, value: text, norm, indices });\n      }\n    }\n\n    return matches\n  }\n}\n\nFuse.version = '7.1.0';\nFuse.createIndex = createIndex;\nFuse.parseIndex = parseIndex;\nFuse.config = Config;\n\n{\n  Fuse.parseQuery = parse;\n}\n\n{\n  register(ExtendedSearch);\n}\n\nexport { Fuse as default };\n","const keywordToCategory = {\r\n    // Food & Dining\r\n    food: 'Food',\r\n    restaurant: 'Food',\r\n    swiggy: 'Food',\r\n    zomato: 'Food',\r\n    meal: 'Food',\r\n    dining: 'Food',\r\n    cafe: 'Food',\r\n    snack: 'Food',\r\n\r\n    // Fuel\r\n    fuel: 'Fuel',\r\n    petrol: 'Fuel',\r\n    diesel: 'Fuel',\r\n    hpcl: 'Fuel',\r\n    iocl: 'Fuel',\r\n    bharat: 'Fuel',\r\n    shell: 'Fuel',\r\n    gas: 'Fuel',\r\n\r\n    // Grocery\r\n    grocery: 'Grocery',\r\n    supermarket: 'Grocery',\r\n    bigbasket: 'Grocery',\r\n    dmart: 'Grocery',\r\n    more: 'Grocery',\r\n    reliance: 'Grocery',\r\n    mart: 'Grocery',\r\n\r\n    // Bills & Utilities\r\n    bill: 'Bills',\r\n    electricity: 'Bills',\r\n    water: 'Bills',\r\n    rent: 'Bills',\r\n    gasbill: 'Bills',\r\n    power: 'Bills',\r\n    broadband: 'Bills',\r\n    airtel: 'Bills',\r\n    jiofiber: 'Bills',\r\n    tata: 'Bills',\r\n\r\n    // Transport\r\n    transport: 'Transport',\r\n    uber: 'Transport',\r\n    ola: 'Transport',\r\n    bus: 'Transport',\r\n    taxi: 'Transport',\r\n    cab: 'Transport',\r\n    metro: 'Transport',\r\n    travel: 'Transport',\r\n    railway: 'Transport',\r\n    irctc: 'Transport',\r\n    flight: 'Transport',\r\n\r\n    // Entertainment & Subscriptions\r\n    movie: 'Entertainment',\r\n    netflix: 'Entertainment',\r\n    prime: 'Entertainment',\r\n    hotstar: 'Entertainment',\r\n    spotify: 'Entertainment',\r\n    youtube: 'Entertainment',\r\n    recharge: 'Entertainment',\r\n\r\n    // Medical\r\n    doctor: 'Medical',\r\n    medicine: 'Medical',\r\n    hospital: 'Medical',\r\n    pharmacy: 'Medical',\r\n    medplus: 'Medical',\r\n    apollo: 'Medical',\r\n    health: 'Medical',\r\n    clinic: 'Medical',\r\n\r\n    // Banking & Transfers\r\n    bank: 'Banking',\r\n    transfer: 'Banking',\r\n    upi: 'Banking',\r\n    neft: 'Banking',\r\n    imps: 'Banking',\r\n    atm: 'Banking',\r\n    withdrawal: 'Banking',\r\n    deposit: 'Banking',\r\n    paytm: 'Banking',\r\n    phonepe: 'Banking',\r\n    gpay: 'Banking',\r\n    wallet: 'Banking',\r\n\r\n    // Shopping\r\n    amazon: 'Shopping',\r\n    flipkart: 'Shopping',\r\n    myntra: 'Shopping',\r\n    meesho: 'Shopping',\r\n    order: 'Shopping',\r\n    online: 'Shopping',\r\n\r\n    // Education\r\n    school: 'Education',\r\n    college: 'Education',\r\n    tuition: 'Education',\r\n    coaching: 'Education',\r\n    fee: 'Education',\r\n\r\n    // Miscellaneous\r\n    donation: 'Others',\r\n    gift: 'Others',\r\n    wedding: 'Others',\r\n    event: 'Others',\r\n    service: 'Others',\r\n\r\n};\r\n\r\nexport default keywordToCategory;\r\n","import Fuse from 'fuse.js';\r\nimport keywordToCategory from './categoryMapper';\r\n\r\nconst keywords = Object.keys(keywordToCategory).map(k => ({ keyword: k, category: keywordToCategory[k] }));\r\n\r\nconst fuse = new Fuse(keywords, {\r\n    keys: ['keyword'],\r\n    threshold: 0.4, // Adjust: 0.0 (strict) to 1.0 (loose)\r\n});\r\n\r\nexport function getCategoryFromDescription(description = '') {\r\n    const lowerDesc = description.toLowerCase();\r\n    const words = lowerDesc.split(/\\s+/);\r\n\r\n    for (let word of words) {\r\n        const result = fuse.search(word);\r\n        if (result.length > 0) {\r\n            return result[0].item.category;\r\n        }\r\n    }\r\n\r\n\r\n    return 'Others'; // fallback category\r\n}\r\n","import { useState } from 'react';\r\nimport Highcharts from 'highcharts';\r\nimport HighchartsReact from 'highcharts-react-official';\r\nimport { getCategoryFromDescription } from '../utils/getCategoryFromDescription';\r\n\r\nfunction CashFlowPieChart({ transactions, tabLabel }) {\r\n    const [showDrilldown, setShowDrilldown] = useState(false);\r\n\r\n    let totalIn = 0;\r\n    let totalOut = 0;\r\n\r\n    const categoryBreakdown = {\r\n        Food: 0,\r\n        Fuel: 0,\r\n        Grocery: 0,\r\n        Bills: 0,\r\n        Transport: 0,\r\n        Entertainment: 0,\r\n        Medical: 0,\r\n        Banking: 0,\r\n        Others: 0\r\n    };\r\n\r\n    transactions.forEach(t => {\r\n        totalIn += t.cashIn || 0;\r\n        totalOut += t.cashOut || 0;\r\n\r\n        if (t.cashOut && t.description) {\r\n            const category = getCategoryFromDescription(t.description);\r\n            categoryBreakdown[category] = (categoryBreakdown[category] || 0) + t.cashOut;\r\n        }\r\n    });\r\n\r\n    const mainChartData = [\r\n        { name: 'Cash In', y: totalIn, color: '#00c49f' },\r\n        {\r\n            name: 'Cash Out',\r\n            y: totalOut,\r\n            color: '#ff8042',\r\n            events: {\r\n                click: () => setShowDrilldown(true)\r\n            }\r\n        }\r\n    ];\r\n\r\n    const categoryData = Object.entries(categoryBreakdown).map(([name, y]) => ({\r\n        name,\r\n        y\r\n    }));\r\n\r\n    const chartOptions = {\r\n        chart: {\r\n            type: 'pie',\r\n            backgroundColor: 'transparent',\r\n            height: showDrilldown ? '400px' : '300px',\r\n            events: {\r\n                click: () => {\r\n                    if (showDrilldown) setShowDrilldown(false);\r\n                }\r\n            }\r\n        },\r\n        title: {\r\n            text: showDrilldown ? `${tabLabel} Cash Out Flow` : `${tabLabel} Cash Flow Distribution`,\r\n            style: {\r\n                fontSize: '16px',\r\n                color: '#fff'\r\n            }\r\n        },\r\n        tooltip: {\r\n            pointFormat: 'Amount: <b>₹{point.y}</b><br/>Percentage: <b>{point.percentage:.1f}%</b>'\r\n        },\r\n        accessibility: {\r\n            point: { valueSuffix: '%' }\r\n        },\r\n        plotOptions: {\r\n            pie: {\r\n                allowPointSelect: true,\r\n                cursor: 'pointer',\r\n                dataLabels: {\r\n                    enabled: true,\r\n                    format: '<b>{point.name}</b><br/>₹{point.y}<br/>({point.percentage:.1f}%)',\r\n                    style: {\r\n                        color: '#fff',\r\n                        textOutline: 'none',\r\n                        fontSize: '11px'\r\n                    }\r\n                }\r\n            }\r\n        },\r\n        legend: {\r\n            align: 'center',\r\n            verticalAlign: 'bottom',\r\n            itemStyle: {\r\n                fontSize: '12px',\r\n                color: '#fff'\r\n            }\r\n        },\r\n        series: [{\r\n            name: showDrilldown ? 'Category' : 'Amount',\r\n            colorByPoint: true,\r\n            data: showDrilldown ? categoryData : mainChartData\r\n        }],\r\n        credits: {\r\n            enabled: false\r\n        }\r\n    };\r\n\r\n    return (\r\n        <div\r\n            style={{\r\n                height: '400px',\r\n                maxWidth: '480px',\r\n                margin: '0 auto',\r\n                transition: 'height 0.3s ease'\r\n            }}\r\n        >\r\n            <HighchartsReact highcharts={Highcharts} options={chartOptions} />\r\n        </div>\r\n    );\r\n\r\n}\r\n\r\nexport default CashFlowPieChart;\r\n","import React from 'react';\r\n\r\nconst NetBalanceOverview = ({ transactions }) => {\r\n    const formatAmount = (num) =>\r\n        Number(num).toLocaleString('en-IN', { minimumFractionDigits: 2 });\r\n    const totalIn = transactions\r\n        .filter(txn => txn.cashIn && txn.cashIn > 0)\r\n        .reduce((sum, txn) => sum + Number(txn.cashIn), 0);\r\n\r\n    const totalOut = transactions\r\n        .filter(txn => txn.cashOut && txn.cashOut > 0)\r\n        .reduce((sum, txn) => sum + Number(txn.cashOut), 0);\r\n\r\n    const netBalance = totalIn - totalOut;\r\n\r\n    return (\r\n        <div style={{\r\n            display: 'flex',\r\n            justifyContent: 'space-around',\r\n            background: '#333',\r\n            color: '#fff',\r\n            padding: '12px',\r\n            margin: '10px 0',\r\n            borderRadius: '8px',\r\n            fontWeight: '500',\r\n            flexWrap: 'wrap',\r\n            textAlign: 'center',\r\n            fontSize: '15px'\r\n        }}>\r\n            <div style={{ margin: '6px 12px', color: totalIn > 0 ? '#4caf50' : '#ccc' }}>\r\n                <strong>Total In:</strong> ₹{formatAmount(totalIn)}\r\n            </div>\r\n            <div style={{ margin: '6px 12px', color: totalOut > 0 ? '#f44336' : '#ccc' }}>\r\n                <strong>Total Out:</strong> ₹{formatAmount(totalOut)}\r\n            </div>\r\n            <div style={{\r\n                margin: '6px 12px',\r\n                color: netBalance > 0 ? '#4caf50' : netBalance < 0 ? '#f44336' : '#fff'\r\n            }}>\r\n                <strong>Net Balance:</strong> ₹{formatAmount(netBalance)}\r\n            </div>\r\n        </div>\r\n\r\n    );\r\n};\r\n\r\n\r\nexport default NetBalanceOverview;\r\n","// DEFLATE is a complex format; to read this code, you should probably check the RFC first:\n// https://tools.ietf.org/html/rfc1951\n// You may also wish to take a look at the guide I made about this program:\n// https://gist.github.com/101arrowz/253f31eb5abc3d9275ab943003ffecad\n// Some of the following code is similar to that of UZIP.js:\n// https://github.com/photopea/UZIP.js\n// However, the vast majority of the codebase has diverged from UZIP.js to increase performance and reduce bundle size.\n// Sometimes 0 will appear where -1 would be more appropriate. This is because usin