idths\r\n    const colWidths = wsData[2].map((_, colIdx) => {\r\n        const maxLen = Math.max(...wsData.map(r => (r[colIdx] ? r[colIdx].toString().length : 0)));\r\n        return { wch: maxLen + 5 };\r\n    });\r\n    ws['!cols'] = colWidths;\r\n\r\n    // Merge app title across all columns\r\n    const balanceRow = wsData.length - 1;\r\n    ws['!merges'] = [\r\n        { s: { r: 0, c: 0 }, e: { r: 0, c: 3 } }, // A1 to D1\r\n\r\n        // Merge C & D in total row\r\n        { s: { r: balanceRow, c: 2 }, e: { r: balanceRow, c: 3 } } // Merge C & D for Balance\r\n    ];\r\n\r\n    // Style app title\r\n    ws['A1'].s = {\r\n        font: { bold: true, sz: 14 },\r\n        alignment: { horizontal: 'center' },\r\n        fill: { fgColor: { rgb: '12aaf1' } }\r\n    };\r\n\r\n    // Style headers\r\n    ['A3', 'B3', 'C3', 'D3'].forEach((cell) => {\r\n        ws[cell].s = {\r\n            font: { bold: true },\r\n            fill: { fgColor: { rgb: '12aaf1' } },\r\n            alignment: { horizontal: 'center', vertical: 'center' },\r\n            border: borderStyle()\r\n        };\r\n    });\r\n\r\n    // Style all data and total cells\r\n    Object.keys(ws).forEach((cell) => {\r\n        if (!cell.startsWith('!') && !ws[cell].s) {\r\n            ws[cell].s = {\r\n                alignment: { horizontal: 'center', vertical: 'center' },\r\n                border: borderStyle()\r\n            };\r\n        }\r\n    });\r\n\r\n    // Style total row (bold + border)\r\n    const lastRowStart = wsData.length - 2;\r\n\r\n    ['B', 'C', 'D'].forEach((col, i) => {\r\n        for (let j = 0; j < 3; j++) {\r\n            const cellAddr = `${col}${lastRowStart + j}`;\r\n            if (ws[cellAddr]) {\r\n                ws[cellAddr].s = {\r\n                    font: { bold: true },\r\n                    alignment: { horizontal: 'center' },\r\n                    border: borderStyle(),\r\n                    fill: j === 2\r\n                        ? { fgColor: { rgb: totalIn - totalOut >= 0 ? 'CCFFCC' : 'FFCCCC' } } // Balance row color\r\n                        : { fgColor: { rgb: 'FFFFCC' } } // Total In/Out rows\r\n                };\r\n            }\r\n        }\r\n    });\r\n\r\n    const totalCell = `C${totalRowIndex}`;\r\n    if (ws[totalCell]) {\r\n        ws[totalCell].s = {\r\n            font: { bold: true },\r\n            alignment: { horizontal: 'center' },\r\n            fill: { fgColor: { rgb: 'FFFFCC' } },\r\n            border: borderStyle()\r\n        };\r\n    }\r\n\r\n    // Optional: style \"Total\" label cell\r\n    if (ws[`A${totalRowIndex}`]) {\r\n        ws[`A${totalRowIndex}`].s = {\r\n            font: { bold: true },\r\n            alignment: { horizontal: 'center' },\r\n            border: borderStyle()\r\n        };\r\n    }\r\n\r\n    // Append and export\r\n    XLSX.utils.book_append_sheet(wb, ws, 'Report');\r\n    const filename = fromDate && toDate\r\n        ? `Cashbook_${fromDate}_to_${toDate}.xlsx`\r\n        : `Cashbook_${new Date().getFullYear()}-${new Date().getMonth() + 1}.xlsx`;\r\n\r\n    const wbout = XLSX.write(wb, { bookType: 'xlsx', type: 'binary' });\r\n    const buf = new ArrayBuffer(wbout.length);\r\n    const view = new Uint8Array(buf);\r\n    for (let i = 0; i !== wbout.length; ++i) view[i] = wbout.charCodeAt(i) & 0xFF;\r\n\r\n    saveAs(new Blob([buf], { type: 'application/octet-stream' }), filename);\r\n}\r\n\r\n// Utility to apply border style\r\nfunction borderStyle() {\r\n    return {\r\n        top: { style: 'thin', color: { rgb: '000000' } },\r\n        bottom: { style: 'thin', color: { rgb: '000000' } },\r\n        left: { style: 'thin', color: { rgb: '000000' } },\r\n        right: { style: 'thin', color: { rgb: '000000' } }\r\n    };\r\n}\r\n\r\n// Utility to format date\r\nfunction formatDate(date) {\r\n    const dd = String(date.getDate()).padStart(2, '0');\r\n    const mm = String(date.getMonth() + 1).padStart(2, '0');\r\n    const yyyy = date.getFullYear();\r\n    const hh = String(date.getHours()).padStart(2, '0');\r\n    const min = String(date.getMinutes()).padStart(2, '0');\r\n    return `${dd}-${mm}-${yyyy} ${hh}:${min}`;\r\n}\r\n","// component/HeaderSection.js\r\nimport { useEffect } from 'react';\r\nimport CashFlowPieChart from './CashFlowPieChart';\r\nimport './css/HeaderSection.css';\r\nimport NetBalanceOverview from './NetBalanceOverview';\r\nimport jsPDF from 'jspdf';\r\nimport autoTable from 'jspdf-autotable';\r\n\r\n\r\nimport $ from 'jquery';\r\nimport 'jquery-ui/ui/widgets/datepicker';\r\nimport 'jquery-ui-dist/jquery-ui.css';\r\nimport { exportToExcel } from '../utils/exportExcel';\r\n\r\nfunction HeaderSection({\r\n    transactions,\r\n    rawtransactions,\r\n    fromDate,\r\n    toDate,\r\n    setFromDate,\r\n    setToDate,\r\n    activeTab,\r\n    email,\r\n    setEmail,\r\n    sendBackup,\r\n    showEmailInput,\r\n    setShowEmailInput\r\n}) {\r\n\r\n    useEffect(() => {\r\n        const parseDate = (str) => {\r\n            const [dd, mm, yyyy] = str.split('-');\r\n            return new Date(`${yyyy}-${mm}-${dd}`);\r\n        };\r\n\r\n        // Initialize From Datepicker\r\n        $('#fromDateInput').datepicker({\r\n            dateFormat: 'dd-mm-yy',\r\n            changeMonth: true,\r\n            changeYear: true,\r\n            showAnim: 'fadeIn',\r\n            onSelect: function (dateText) {\r\n                setFromDate(dateText);\r\n\r\n                const minToDate = parseDate(dateText);\r\n\r\n                // Reset To Date if it's before the new From Date\r\n                if (toDate && parseDate(toDate) < minToDate) {\r\n                    setToDate('');\r\n                    $('#toDateInput').val('');\r\n                }\r\n\r\n                // Reinitialize To Datepicker with updated minDate\r\n                $('#toDateInput').datepicker('option', 'minDate', minToDate);\r\n            }\r\n        });\r\n\r\n        // Initialize To Datepicker\r\n        $('#toDateInput').datepicker({\r\n            dateFormat: 'dd-mm-yy',\r\n            changeMonth: true,\r\n            changeYear: true,\r\n            showAnim: 'fadeIn',\r\n            onSelect: function (dateText) {\r\n                setToDate(dateText);\r\n            }\r\n        });\r\n\r\n        // If fromDate already selected, set minDate initially\r\n        if (fromDate) {\r\n            const minToDate = parseDate(fromDate);\r\n            $('#toDateInput').datepicker('option', 'minDate', minToDate);\r\n        }\r\n    }, [fromDate, toDate, setFromDate, setToDate]);\r\n\r\n    const exportPDF = () => {\r\n        const doc = new jsPDF();\r\n        doc.text(\"CashBook Report\", 14, 15);\r\n\r\n        const formatDate = (dateStr) => {\r\n            const date = new Date(dateStr);\r\n            const dd = String(date.getDate()).padStart(2, '0');\r\n            const mm = String(date.getMonth() + 1).padStart(2, '0');\r\n            const yyyy = date.getFullYear();\r\n            const hh = String(date.getHours()).padStart(2, '0');\r\n            const min = String(date.getMinutes()).padStart(2, '0');\r\n            return `${dd}-${mm}-${yyyy} ${hh}:${min}`;\r\n        };\r\n\r\n        const tableColumn = [\"Date\", \"Type\", \"Amount\", \"Description\"];\r\n        let totalIn = 0;\r\n        let totalOut = 0;\r\n        const tableRows = rawtransactions.map(txn => {\r\n            const amount = txn.cashIn > 0 ? txn.cashIn : txn.cashOut;\r\n            const type = txn.cashIn > 0 ? 'Cash In' : 'Cash Out';\r\n            if (txn.cashIn > 0) totalIn += txn.cashIn;\r\n            else totalOut += txn.cashOut;\r\n            return [\r\n                formatDate(txn.date),\r\n                type,\r\n                txn.description || '',\r\n                `${amount}`\r\n\r\n            ];\r\n        });\r\n\r\n        autoTable(doc, {\r\n            startY: 20,\r\n            head: [tableColumn],\r\n            body: tableRows,\r\n        });\r\n        const netBalance = totalIn - totalOut;\r\n        const formatAmount = (num) =>\r\n            Number(num).toLocaleString('en-IN', { minimumFractionDigits: 2 });\r\n        const summaryRows = [\r\n            ['Total Cash In', `INR ${formatAmount(totalIn)}`],\r\n            ['Total Cash Out', `INR ${formatAmount(totalOut)}`],\r\n            [\r\n                { content: 'Net Balance', styles: { fontStyle: 'bold' } },\r\n                {\r\n                    content: `INR ${formatAmount(netBalance)}`,\r\n                    styles: { textColor: netBalance >= 0 ? 'green' : 'red' }\r\n                }\r\n            ]\r\n        ];\r\n        autoTable(doc, {\r\n            startY: doc.lastAutoTable.finalY + 10,\r\n            head: [['Summary', 'Amount']],\r\n            body: summaryRows,\r\n            theme: 'grid',\r\n            styles: { fontStyle: 'bold' }\r\n        });\r\n\r\n        // Optional: Add footer (date & page number)\r\n        const pageCount = doc.internal.getNumberOfPages();\r\n        for (let i = 1; i <= pageCount; i++) {\r\n            doc.setPage(i);\r\n            doc.setFontSize(10);\r\n            doc.text(\r\n                `Generated on ${formatDate(new Date())}`,\r\n                14,\r\n                doc.internal.pageSize.getHeight() - 10\r\n            );\r\n            doc.text(\r\n                `Page ${i} of ${pageCount}`,\r\n                doc.internal.pageSize.getWidth() - 40,\r\n                doc.internal.pageSize.getHeight() - 10\r\n            );\r\n        }\r\n\r\n        doc.save(\"Cashbook_Report.pdf\");\r\n    };\r\n\r\n    return (\r\n        <div className=\"header-layout\">\r\n\r\n            <div id='pieChartDiv'>\r\n                <CashFlowPieChart transactions={transactions} tabLabel={activeTab} />\r\n            </div>\r\n            <NetBalanceOverview transactions={rawtransactions} />\r\n            <div className=\"excel-export\">\r\n                <label>📊 Download Reports in Excel:</label>\r\n                <div className=\"date-inputs\">\r\n                    <div className=\"date-input-group\">\r\n                        <label htmlFor=\"fromDateInput\">From Date</label>\r\n                        <input\r\n                            type=\"text\"\r\n                            id=\"fromDateInput\"\r\n                            placeholder=\"DD-MM-YYYY\"\r\n                            value={fromDate}\r\n                            readOnly\r\n                            onChange={(e) => setFromDate(e.target.value)}\r\n                        />\r\n                    </div>\r\n                    <div className=\"date-input-group\">\r\n                        <label htmlFor=\"toDateInput\">To Date</label>\r\n                        <input\r\n                            type=\"text\"\r\n                            id=\"toDateInput\"\r\n                            placeholder=\"DD-MM-YYYY\"\r\n                            value={toDate}\r\n                            readOnly\r\n                            onChange={(e) => setToDate(e.target.value)}\r\n                        />\r\n                    </div>\r\n                    <div className=\"download-button-wrapper\">\r\n                        <button onClick={() => exportToExcel(transactions, fromDate, toDate, setFromDate, setToDate)}>\r\n                            📥 Download\r\n                        </button>\r\n                        <button onClick={exportPDF} className=\"btn btn-download\">\r\n                            Download PDF\r\n                        </button>\r\n\r\n\r\n                        <button\r\n                            style={{ marginLeft: '0.5rem', backgroundColor: '#dc3545' }}\r\n                            onClick={() => {\r\n                                setFromDate('');\r\n                                setToDate('');\r\n                                $('#fromDateInput').datepicker('setDate', null);\r\n                                $('#toDateInput').datepicker('setDate', null);\r\n                                $('#toDateInput').datepicker('option', 'minDate', null);\r\n                            }}\r\n                        >\r\n                            ❌ Clear\r\n                        </button>\r\n\r\n                    </div>\r\n\r\n                    {/* Gmail Backup Section */}\r\n\r\n                    <div\r\n                        style={{\r\n                            position: 'relative',\r\n                            height: '56px', // Reserve space\r\n                            marginTop: '10px',\r\n                            width: '100%',\r\n                        }}\r\n                    >\r\n                        {/* 📧 Toggle Button */}\r\n                        <div\r\n                            style={{\r\n                                position: 'absolute',\r\n                                top: 0,\r\n                                left: 0,\r\n                                right: 0,\r\n                                display: showEmailInput ? 'none' : 'flex',\r\n                                alignItems: 'center',\r\n                            }}\r\n                        >\r\n                            <button\r\n                                onClick={() => setShowEmailInput(true)}\r\n                                style={{\r\n                                    padding: '8px 16px',\r\n                                    borderRadius: '4px',\r\n                                    border: 'none',\r\n                                    backgroundColor: '#28a745',\r\n                                    color: '#fff',\r\n                                    cursor: 'pointer',\r\n                                }}\r\n                            >\r\n                                📧 Send Backup to Gmail\r\n                            </button>\r\n                        </div>\r\n\r\n                        {/* 📤 Input + Send + Cancel */}\r\n                        <div\r\n                            style={{\r\n                                position: 'absolute',\r\n                                top: 0,\r\n                                left: 0,\r\n                                right: 0,\r\n                                display: showEmailInput ? 'flex' : 'none',\r\n                                gap: '10px',\r\n                                alignItems: 'center',\r\n                                flexWrap: 'wrap',\r\n                            }}\r\n                        >\r\n                            <input\r\n                                type=\"email\"\r\n                                placeholder=\"Enter your Gmail\"\r\n                                value={email}\r\n                                onChange={(e) => setEmail(e.target.value)}\r\n                                style={{\r\n                                    padding: '8px',\r\n                                    borderRadius: '4px',\r\n                                    border: '1px solid #ccc',\r\n                                    minWidth: '220px',\r\n                                    flexGrow: 1,\r\n                                }}\r\n                            />\r\n                            <button\r\n                                onClick={sendBackup}\r\n                                style={{\r\n                                    padding: '8px 16px',\r\n                                    borderRadius: '4px',\r\n                                    border: 'none',\r\n                                    backgroundColor: '#007bff',\r\n                                    color: '#fff',\r\n                                    cursor: 'pointer',\r\n                                }}\r\n                            >\r\n                                📤 Send Backup\r\n                            </button>\r\n                            <button\r\n                                onClick={() => setShowEmailInput(false)}\r\n                                style={{\r\n                                    padding: '8px 16px',\r\n                                    borderRadius: '4px',\r\n                                    border: 'none',\r\n                                    backgroundColor: '#dc3545',\r\n                                    color: '#fff',\r\n                                    cursor: 'pointer',\r\n                                }}\r\n                            >\r\n                                ✖ Cancel\r\n                            </button>\r\n                        </div>\r\n                    </div>\r\n\r\n\r\n\r\n                </div>\r\n            </div>\r\n        </ div>\r\n    );\r\n}\r\n\r\nexport default HeaderSection;\r\n","// component/SearchFilterPanel.js\r\nimport React from 'react';\r\n\r\nconst SearchFilterPanel = ({\r\n    searchText, setSearchText,\r\n    filterType, setFilterType,\r\n    minAmount, setMinAmount,\r\n    maxAmount, setMaxAmount\r\n}) => {\r\n    return (\r\n        <div style={{\r\n            display: 'flex',\r\n            flexWrap: 'wrap',\r\n            gap: '12px',\r\n            marginBottom: '15px',\r\n            background: '#2d2d2d',\r\n            padding: '10px',\r\n            borderRadius: '8px',\r\n            color: '#fff',\r\n        }}>\r\n            <input\r\n                type=\"text\"\r\n                placeholder=\"🔍 Search description\"\r\n                value={searchText}\r\n                onChange={(e) => setSearchText(e.target.value)}\r\n                style={{ padding: '8px', borderRadius: '4px', border: 'none', width: '180px' }}\r\n            />\r\n            <select\r\n                value={filterType}\r\n                onChange={(e) => setFilterType(e.target.value)}\r\n                style={{ padding: '8px', borderRadius: '4px' }}\r\n            >\r\n                <option value=\"All\">All</option>\r\n                <option value=\"Cash In\">Cash In</option>\r\n                <option value=\"Cash Out\">Cash Out</option>\r\n            </select>\r\n            <input\r\n                type=\"number\"\r\n                placeholder=\"Min Amount\"\r\n                value={minAmount}\r\n                onChange={(e) => setMinAmount(e.target.value)}\r\n                style={{ padding: '8px', borderRadius: '4px', width: '100px' }}\r\n            />\r\n            <input\r\n                type=\"number\"\r\n                placeholder=\"Max Amount\"\r\n                value={maxAmount}\r\n                onChange={(e) => setMaxAmount(e.target.value)}\r\n                style={{ padding: '8px', borderRadius: '4px', width: '100px' }}\r\n            />\r\n            <button\r\n                onClick={() => {\r\n                    setSearchText('');\r\n                    setFilterType('All');\r\n                    setMinAmount('');\r\n                    setMaxAmount('');\r\n                }}\r\n                style={{ padding: '8px 12px', borderRadius: '4px', background: '#ff4444', color: '#fff', border: 'none' }}\r\n            >\r\n                Clear\r\n            </button>\r\n        </div>\r\n    );\r\n};\r\n\r\nexport default SearchFilterPanel;\r\n","// component/TransactionSection.js\r\nimport React from 'react';\r\nimport SearchFilterPanel from './SearchFilterPanel';\r\n\r\n\r\nfunction TransactionSection({\r\n    transactions,\r\n    formType,\r\n    description,\r\n    cashIn,\r\n    cashOut,\r\n    editId,\r\n    setFormType,\r\n    setDescription,\r\n    setCashIn,\r\n    setCashOut,\r\n    startEdit,\r\n    cancelEdit,\r\n    deleteTransaction,\r\n    submitTransaction,\r\n    activeTab,\r\n    setActiveTab,\r\n    searchText, setSearchText,\r\n    filterType, setFilterType,\r\n    minAmount, setMinAmount,\r\n    maxAmount, setMaxAmount\r\n}) {\r\n\r\n    const [menuOpen, setMenuOpen] = React.useState(false);\r\n\r\n    const now = new Date();\r\n    const lastMonthStart = new Date(now.getFullYear(), now.getMonth() - 1, 1);\r\n    const lastMonthEnd = new Date(now.getFullYear(), now.getMonth(), 0);\r\n\r\n    function getWeekNumber(d) {\r\n        const date = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));\r\n        const dayNum = date.getUTCDay() || 7;\r\n        date.setUTCDate(date.getUTCDate() + 4 - dayNum);\r\n        const yearStart = new Date(Date.UTC(date.getUTCFullYear(), 0, 1));\r\n        return Math.ceil(((date - yearStart) / 86400000 + 1) / 7);\r\n    }\r\n\r\n    const filteredTransactions = transactions.filter((t) => {\r\n        const date = new Date(t.date);\r\n        const currentYear = now.getFullYear();\r\n        const currentMonth = now.getMonth();\r\n        const currentWeek = getWeekNumber(now);\r\n        const txWeek = getWeekNumber(date);\r\n\r\n        switch (activeTab) {\r\n            case 'Daily':\r\n                return date.toDateString() === now.toDateString();\r\n            case 'Weekly':\r\n                return date.getFullYear() === currentYear && txWeek === currentWeek;\r\n            case 'Monthly':\r\n                return date.getFullYear() === currentYear && date.getMonth() === currentMonth;\r\n\r\n            case 'LastMonth':\r\n                return date >= lastMonthStart && date <= lastMonthEnd;\r\n            default:\r\n                return true;\r\n        }\r\n    });\r\n\r\n\r\n    function formatDate(date) {\r\n        const dd = String(date.getDate()).padStart(2, '0');\r\n        const mm = String(date.getMonth() + 1).padStart(2, '0');\r\n        const yyyy = date.getFullYear();\r\n        const hh = String(date.getHours()).padStart(2, '0');\r\n        const min = String(date.getMinutes()).padStart(2, '0');\r\n        return `${dd}-${mm}-${yyyy} ${hh}:${min}`;\r\n    }\r\n\r\n\r\n\r\n\r\n\r\n    const totalCashIn = filteredTransactions.reduce((sum, t) => sum + t.cashIn, 0);\r\n    const totalCashOut = filteredTransactions.reduce((sum, t) => sum + t.cashOut, 0);\r\n    const balance = totalCashIn - totalCashOut;\r\n\r\n\r\n    const filteredList = filteredTransactions.filter(txn => {\r\n        const descMatch = (txn.description || '').toLowerCase().includes(searchText.toLowerCase());\r\n        const amount = txn.cashIn > 0 ? txn.cashIn : txn.cashOut;\r\n\r\n        const typeMatch =\r\n            filterType === 'All' ||\r\n            (filterType === 'Cash In' && txn.cashIn > 0) ||\r\n            (filterType === 'Cash Out' && txn.cashOut > 0);\r\n\r\n        const minMatch = !minAmount || amount >= parseFloat(minAmount);\r\n        const maxMatch = !maxAmount || amount <= parseFloat(maxAmount);\r\n\r\n        return descMatch && typeMatch && minMatch && maxMatch;\r\n    });\r\n\r\n\r\n    return (\r\n        <section className=\"cash-book\">\r\n            <div className=\"tabs-container\">\r\n                <div className=\"menu-toggle\" onClick={() => setMenuOpen(!menuOpen)}>\r\n                    ☰ Menu\r\n                </div>\r\n                <div className={`tabs ${menuOpen ? 'show' : 'hide'}`}>\r\n                    {['Daily', 'Weekly', 'Monthly', 'LastMonth', 'All'].map((tab) => (\r\n                        <button\r\n                            key={tab}\r\n                            className={activeTab === tab ? 'active' : ''}\r\n                            onClick={() => {\r\n                                setActiveTab(tab);\r\n                                setMenuOpen(false);\r\n                            }}\r\n                        >\r\n                            {tab === 'LastMonth' ? 'Last Month' : tab}\r\n                        </button>\r\n                    ))}\r\n                </div>\r\n            </div>\r\n\r\n            <div className=\"transaction-type-buttons\">\r\n                <button\r\n                    className={formType === 'cashIn' ? 'active' : ''}\r\n                    onClick={() => setFormType('cashIn')}\r\n                >\r\n                    💰 Cash In\r\n                </button>\r\n                <button\r\n                    className={formType === 'cashOut' ? 'active' : ''}\r\n                    onClick={() => setFormType('cashOut')}\r\n                >\r\n                    💸 Cash Out\r\n                </button>\r\n            </div>\r\n\r\n            {formType && (\r\n                <div className=\"add-transaction-form\">\r\n                    <input\r\n                        type=\"text\"\r\n                        placeholder=\"Description\"\r\n                        value={description}\r\n                        onChange={(e) => setDescription(e.target.value)}\r\n                    />\r\n                    {formType === 'cashIn' && (\r\n                        <input\r\n                            type=\"number\"\r\n                            placeholder=\"Cash In\"\r\n                            value={cashIn}\r\n                            onChange={(e) => setCashIn(e.target.value)}\r\n                        />\r\n                    )}\r\n                    {formType === 'cashOut' && (\r\n                        <input\r\n                            type=\"number\"\r\n                            placeholder=\"Cash Out\"\r\n                            value={cashOut}\r\n                            onChange={(e) => setCashOut(e.target.value)}\r\n                        />\r\n                    )}\r\n                    <button onClick={submitTransaction}>\r\n                        {editId ? 'Update' : 'Add'} {formType === 'cashIn' ? 'Cash In' : 'Cash Out'}\r\n                    </button>\r\n                    {editId && <button onClick={cancelEdit}>Cancel</button>}\r\n                </div>\r\n            )}\r\n            <SearchFilterPanel\r\n                searchText={searchText}\r\n                setSearchText={setSearchText}\r\n                filterType={filterType}\r\n                setFilterType={setFilterType}\r\n                minAmount={minAmount}\r\n                setMinAmount={setMinAmount}\r\n                maxAmount={maxAmount}\r\n                setMaxAmount={setMaxAmount}\r\n            />\r\n\r\n            <div className=\"transactions-table\">\r\n                <table>\r\n                    <thead>\r\n                        <tr>\r\n                            <th>Date</th>\r\n                            <th>Cash In</th>\r\n                            <th>Cash Out</th>\r\n                        </tr>\r\n                    </thead>\r\n                    <tbody>\r\n                        {filteredList.map((transaction) => (\r\n                            <tr key={transaction.id}>\r\n                                <td>\r\n                                    <div className=\"date\">{formatDate(new Date(transaction.date))}</div>\r\n                                    <div className=\"description\">{transaction.description}</div>\r\n                                    <div className=\"actions\">\r\n                                        <button\r\n                                            className=\"edit-btn\"\r\n                                            onClick={() => startEdit(transaction)}\r\n                                        >\r\n                                            ✏️ Edit\r\n                                        </button>\r\n                                        <button\r\n                                            className=\"delete-btn\"\r\n                                            onClick={() => {\r\n                                                if (editId === transaction.id) cancelEdit();\r\n                                                deleteTransaction(transaction.id);\r\n                                            }}\r\n                                        >\r\n                                            🗑️ Delete\r\n                                        </button>\r\n                                    </div>\r\n                                </td>\r\n                                <td className=\"cash-in\">\r\n                                    {transaction.cashIn > 0 ? `₹${transaction.cashIn.toLocaleString()}` : ''}\r\n                                </td>\r\n                                <td className=\"cash-out\">\r\n                                    {transaction.cashOut > 0 ? `₹${transaction.cashOut.toLocaleString()}` : ''}\r\n                                </td>\r\n                            </tr>\r\n                        ))}\r\n                    </tbody>\r\n                </table>\r\n            </div>\r\n\r\n            <div className=\"totals\">\r\n                <div>Total Cash In: ₹{totalCashIn.toLocaleString()}</div>\r\n                <div>Total Cash Out: ₹{totalCashOut.toLocaleString()}</div>\r\n                <div className={`balance ${balance < 0 ? 'negative' : ''}`}>\r\n                    Balance: ₹{Math.abs(balance).toLocaleString()}\r\n                </div>\r\n            </div>\r\n        </section>\r\n    );\r\n}\r\n\r\nexport default TransactionSection;\r\n","// component/Navbar.js\r\nimport React from 'react';\r\nimport './css/Navbar.css'; // optional CSS\r\n\r\nfunction Navbar() {\r\n    return (\r\n        <nav className=\"navbar\">\r\n            <div className=\"navbar-brand\">💼 My Cash Book</div>\r\n        </nav>\r\n    );\r\n}\r\n\r\nexport default Navbar;\r\n","import React, { useEffect, useState } from 'react';\r\nimport './App.css';\r\nimport './utils/ExcelSheet.css';\r\nimport useTransactions from './component/TransactionManager';\r\n// ✅ Working\r\nimport * as XLSX from 'xlsx-js-style';\r\n\r\nimport { saveAs } from 'file-saver';\r\nimport $ from 'jquery';\r\nimport 'jquery-ui/ui/widgets/datepicker';\r\nimport 'jquery-ui-dist/jquery-ui.css';\r\n\r\nimport HeaderSection from './component/HeaderSection';\r\nimport TransactionSection from './component/TransactionSection';\r\nimport Navbar from './component/Navbar';\r\n\r\nfunction App() {\r\n  const {\r\n    transactions,\r\n    formType,\r\n    description,\r\n    cashIn,\r\n    cashOut,\r\n    editId,\r\n    setFormType,\r\n    setDescription,\r\n    setCashIn,\r\n    setCashOut,\r\n    startEdit,\r\n    cancelEdit,\r\n    deleteTransaction,\r\n    submitTransaction,\r\n  } = useTransactions();\r\n\r\n  const [fromDate, setFromDate] = useState('');\r\n  const [toDate, setToDate] = useState('');\r\n  const [activeTab, setActiveTab] = useState('Daily');\r\n  const [searchText, setSearchText] = useState('');\r\n  const [filterType, setFilterType] = useState('All'); // 'All', 'Cash In', 'Cash Out'\r\n  const [minAmount, setMinAmount] = useState('');\r\n  const [maxAmount, setMaxAmount] = useState('');\r\n  const [isDarkMode, setIsDarkMode] = useState(true);\r\n  const [showEmailInput, setShowEmailInput] = useState(false);\r\n  const [email, setEmail] = useState('');\r\n\r\n  useEffect(() => {\r\n    document.body.className = isDarkMode ? 'dark-mode' : 'light-mode';\r\n  }, [isDarkMode]);\r\n\r\n  // eslint-disable-next-line \r\n  useEffect(() => {\r\n    const parseDate = (str) => {\r\n      const [dd, mm, yyyy] = str.split('-');\r\n      return new Date(`${yyyy}-${mm}-${dd}`);\r\n    };\r\n\r\n    // FROM Date Picker\r\n    $('#fromDateInput').datepicker({\r\n      dateFormat: 'dd-mm-yy',\r\n      changeMonth: true,\r\n      changeYear: true,\r\n      showAnim: 'fadeIn',\r\n      onSelect: function (selectedDate) {\r\n        setFromDate(selectedDate);\r\n\r\n        const minToDate = parseDate(selectedDate);\r\n\r\n        $('#toDateInput').datepicker('destroy');\r\n        $('#toDateInput').datepicker({\r\n          dateFormat: 'dd-mm-yy',\r\n          changeMonth: true,\r\n          changeYear: true,\r\n          showAnim: 'fadeIn',\r\n          minDate: minToDate,\r\n          onSelect: function (toDateText) {\r\n            setToDate(toDateText);\r\n          },\r\n        });\r\n\r\n        if (toDate && parseDate(toDate) < minToDate) {\r\n          setToDate('');\r\n          $('#toDateInput').val('');\r\n        }\r\n      },\r\n    });\r\n\r\n    // TO Date Picker Initial (no restriction)\r\n    $('#toDateInput').datepicker({\r\n      dateFormat: 'dd-mm-yy',\r\n      changeMonth: true,\r\n      changeYear: true,\r\n      showAnim: 'fadeIn',\r\n      onSelect: function (dateText) {\r\n        setToDate(dateText);\r\n      },\r\n    });\r\n  }, [toDate]);\r\n\r\n  function formatDate(date) {\r\n    const dd = String(date.getDate()).padStart(2, '0');\r\n    const mm = String(date.getMonth() + 1).padStart(2, '0');\r\n    const yyyy = date.getFullYear();\r\n    const hh = String(date.getHours()).padStart(2, '0');\r\n    const min = String(date.getMinutes()).padStart(2, '0');\r\n    return `${dd}-${mm}-${yyyy} ${hh}:${min}`;\r\n  }\r\n\r\n  function downloadExcel(from, to) {\r\n    let exportData = [];\r\n\r\n    const parseDate = (str) => {\r\n      const [dd, mm, yyyy] = str.split('-');\r\n      return new Date(`${yyyy}-${mm}-${dd}`);\r\n    };\r\n\r\n    if (from && to) {\r\n      const fromTime = parseDate(from).setHours(0, 0, 0, 0);\r\n      const toTime = parseDate(to).setHours(23, 59, 59, 999);\r\n\r\n      exportData = transactions.filter((t) => {\r\n        const txTime = new Date(t.date).getTime();\r\n        return txTime >= fromTime && txTime <= toTime;\r\n      });\r\n    } else {\r\n      const now = new Date();\r\n      const currentYear = now.getFullYear();\r\n      const currentMonth = now.getMonth();\r\n\r\n      exportData = transactions.filter((t) => {\r\n        const date = new Date(t.date);\r\n        return date.getFullYear() === currentYear && date.getMonth() === currentMonth;\r\n      });\r\n    }\r\n\r\n    const data = exportData.map((t) => ({\r\n      Date: formatDate(new Date(t.date)),\r\n      Description: t.description,\r\n      'Cash In': t.cashIn || '',\r\n      'Cash Out': t.cashOut || '',\r\n    }));\r\n\r\n    const worksheet = XLSX.utils.json_to_sheet(data);\r\n    const workbook = XLSX.utils.book_new();\r\n    XLSX.utils.book_append_sheet(workbook, worksheet, 'Export');\r\n\r\n    const now = new Date();\r\n    const fileName =\r\n      from && to\r\n        ? `Cashbook_${from}_to_${to}.xlsx`\r\n        : `Cashbook_${now.getFullYear()}-${now.getMonth() + 1}.xlsx`;\r\n\r\n    const excelBuffer = XLSX.write(workbook, { bookType: 'xlsx', type: 'array' });\r\n    const fileData = new Blob([excelBuffer], { type: 'application/octet-stream' });\r\n    saveAs(fileData, fileName);\r\n\r\n    setFromDate('');\r\n    setToDate('');\r\n  }\r\n\r\n  const now = new Date();\r\n  const getWeekNumber = (d) => {\r\n    const date = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));\r\n    const dayNum = date.getUTCDay() || 7;\r\n    date.setUTCDate(date.getUTCDate() + 4 - dayNum);\r\n    const yearStart = new Date(Date.UTC(date.getUTCFullYear(), 0, 1));\r\n    return Math.ceil(((date - yearStart) / 86400000 + 1) / 7);\r\n  };\r\n\r\n  const lastMonthStart = new Date(now.getFullYear(), now.getMonth() - 1, 1);\r\n  const lastMonthEnd = new Date(now.getFullYear(), now.getMonth(), 0);\r\n\r\n  const filteredTransactionsWithCurrentMonth = transactions.filter((t) => {\r\n    const date = new Date(t.date);\r\n    const currentYear = now.getFullYear();\r\n    const currentMonth = now.getMonth();\r\n    return date.getFullYear() === currentYear && date.getMonth() === currentMonth\r\n  });\r\n\r\n  const filteredTransactions = transactions.filter((t) => {\r\n    const date = new Date(t.date);\r\n    const currentYear = now.getFullYear();\r\n    const currentMonth = now.getMonth();\r\n    const currentWeek = getWeekNumber(now);\r\n    const txWeek = getWeekNumber(date);\r\n\r\n    switch (activeTab) {\r\n      case 'Daily':\r\n        return date.toDateString() === now.toDateString();\r\n      case 'Weekly':\r\n        return date.getFullYear() === currentYear && txWeek === currentWeek;\r\n      case 'Monthly':\r\n        return date.getFullYear() === currentYear && date.getMonth() === currentMonth;\r\n      case 'LastMonth':\r\n        return date >= lastMonthStart && date <= lastMonthEnd;\r\n      default:\r\n        return true;\r\n    }\r\n  });\r\n\r\n  const sendBackup = async () => {\r\n    if (!email.trim() || !email.includes('@')) {\r\n      alert('Please enter a valid Gmail address.');\r\n      return;\r\n    }\r\n\r\n    try {\r\n      const response = await fetch('http://localhost:5000/send-backup', {\r\n        method: 'POST',\r\n        headers: { 'Content-Type': 'application/json' },\r\n        body: JSON.stringify({\r\n          email,\r\n          data: transactions,\r\n        }),\r\n      });\r\n\r\n      const result = await response.text();\r\n      alert(result);\r\n    } catch (error) {\r\n      console.error('Error sending backup:', error);\r\n      alert('Failed to send backup. Please try again.');\r\n    }\r\n  };\r\n\r\n  return (\r\n    <div className=\"app\">\r\n      {/* Dark Mode Toggle */}\r\n      <div\r\n        style={{\r\n          display: 'flex',\r\n          justifyContent: 'space-between',\r\n          alignItems: 'center',\r\n          marginBottom: '20px',\r\n          flexWrap: 'wrap',\r\n        }}\r\n      >\r\n        <button\r\n          onClick={() => setIsDarkMode(!isDarkMode)}\r\n          style={{\r\n            padding: '8px 16px',\r\n            borderRadius: '6px',\r\n            backgroundColor: isDarkMode ? '#fff' : '#333',\r\n            color: isDarkMode ? '#000' : '#fff',\r\n            border: 'none',\r\n            cursor: 'pointer',\r\n            marginTop: '10px',\r\n          }}\r\n          aria-label=\"Toggle dark/light mode\"\r\n        >\r\n          {isDarkMode ? '☀ Light Mode' : '🌙 Dark Mode'}\r\n        </button>\r\n      </div>\r\n\r\n      {/* Navbar Section */}\r\n      <div>\r\n        <Navbar />\r\n      </div>\r\n\r\n      {/* Header Section */}\r\n      <div>\r\n        <header>\r\n          <HeaderSection\r\n            transactions={filteredTransactions}\r\n            rawtransactions={filteredTransactionsWithCurrentMonth}\r\n            fromDate={fromDate}\r\n            toDate={toDate}\r\n            setFromDate={setFromDate}\r\n            setToDate={setToDate}\r\n            downloadExcel={downloadExcel}\r\n            activeTab={activeTab}\r\n            email={email}\r\n            setEmail={setEmail}\r\n            sendBackup={sendBackup}\r\n            showEmailInput={showEmailInput}\r\n            setShowEmailInput={setShowEmailInput}\r\n          />\r\n        </header>\r\n      </div>\r\n\r\n      {/* Main Content Section */}\r\n      <div>\r\n        <main>\r\n          <TransactionSection\r\n            transactions={transactions}\r\n            formType={formType}\r\n            description={description}\r\n            cashIn={cashIn}\r\n            cashOut={cashOut}\r\n            editId={editId}\r\n            setFormType={setFormType}\r\n            setDescription={setDescription}\r\n            setCashIn={setCashIn}\r\n            setCashOut={setCashOut}\r\n            startEdit={startEdit}\r\n            cancelEdit={cancelEdit}\r\n            deleteTransaction={deleteTransaction}\r\n            submitTransaction={submitTransaction}\r\n            activeTab={activeTab}\r\n            setActiveTab={setActiveTab}\r\n            searchText={searchText}\r\n            setSearchText={setSearchText}\r\n            filterType={filterType}\r\n            setFilterType={setFilterType}\r\n            minAmount={minAmount}\r\n            setMinAmount={setMinAmount}\r\n            maxAmount={maxAmount}\r\n            setMaxAmount={setMaxAmount}\r\n          />\r\n        </main>\r\n      </div>\r\n    </div>\r\n  );\r\n}\r\n\r\nexport default App;\r\n","// TransactionManager.js\r\nimport { useState, useEffect } from 'react';\r\n\r\nexport default function useTransactions() {\r\n    const [transactions, setTransactions] = useState([]);\r\n    const [editId, setEditId] = useState(null);\r\n    const [formType, setFormType] = useState(null);\r\n    const [description, setDescription] = useState('');\r\n    const [cashIn, setCashIn] = useState('');\r\n    const [cashOut, setCashOut] = useState('');\r\n\r\n    useEffect(() => {\r\n        const saved = localStorage.getItem('transactions');\r\n        if (saved) setTransactions(JSON.parse(saved));\r\n    }, []);\r\n\r\n    useEffect(() => {\r\n        localStorage.setItem('transactions', JSON.stringify(transactions));\r\n    }, [transactions]);\r\n\r\n    const startEdit = (txn) => {\r\n        setFormType(txn.cashIn > 0 ? 'cashIn' : 'cashOut');\r\n        setDescription(txn.description);\r\n        setCashIn(txn.cashIn || '');\r\n        setCashOut(txn.cashOut || '');\r\n        setEditId(txn.id);\r\n    };\r\n\r\n    const cancelEdit = () => {\r\n        setFormType(null);\r\n        setDescription('');\r\n        setCashIn('');\r\n        setCashOut('');\r\n        setEditId(null);\r\n    };\r\n\r\n    const deleteTransaction = (id) => {\r\n        if (window.confirm('Delete this transaction?')) {\r\n            setTransactions(transactions.filter(t => t.id !== id));\r\n        }\r\n    };\r\n\r\n    const submitTransaction = () => {\r\n        const cashInValue = parseFloat(cashIn);\r\n        const cashOutValue = parseFloat(cashOut);\r\n        const now = new Date();\r\n\r\n        if (!description.trim()) {\r\n            alert('Please enter a description');\r\n            return;\r\n        }\r\n\r\n        if (\r\n            (formType === 'cashIn' && (isNaN(cashInValue) || cashInValue <= 0)) ||\r\n            (formType === 'cashOut' && (isNaN(cashOutValue) || cashOutValue <= 0))\r\n        ) {\r\n            alert('Please enter a valid amount');\r\n            return;\r\n        }\r\n\r\n        const newTxn = {\r\n            id: editId || Date.now(),\r\n            date: editId ? transactions.find(t => t.id === editId).date : now,\r\n            description: description.trim(),\r\n            cashIn: formType === 'cashIn' ? cashInValue : 0,\r\n            cashOut: formType === 'cashOut' ? cashOutValue : 0,\r\n        };\r\n\r\n        if (editId) {\r\n            setTransactions(transactions.map(t => t.id === editId ? newTxn : t));\r\n        } else {\r\n            setTransactions([newTxn, ...transactions]);\r\n        }\r\n\r\n        cancelEdit();\r\n    };\r\n\r\n    return {\r\n        transactions,\r\n        formType,\r\n        description,\r\n        cashIn,\r\n        cashOut,\r\n        editId,\r\n        setFormType,\r\n        setDescription,\r\n        setCashIn,\r\n        setCashOut,\r\n        startEdit,\r\n        cancelEdit,\r\n        deleteTransaction,\r\n        submitTransaction\r\n    };\r\n}\r\n","const reportWebVitals = onPerfEntry => {\n  if (onPerfEntry && onPerfEntry instanceof Function) {\n    import('web-vitals').then(({ getCLS, getFID, getFCP, getLCP, getTTFB }) => {\n      getCLS(onPerfEntry);\n      getFID(onPerfEntry);\n      getFCP(onPerfEntry);\n      getLCP(onPerfEntry);\n      getTTFB(onPerfEntry);\n    });\n  }\n};\n\nexport default reportWebVitals;\n","// CRA default service worker registration helper\r\nconst isLocalhost = Boolean(\r\n    window.location.hostname === 'localhost' ||\r\n    window.location.hostname === '[::1]' ||\r\n    window.location.hostname.match(\r\n        /^127(?:\\.(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)){3}$/\r\n    )\r\n);\r\n\r\nexport function register(config) {\r\n    if (process.env.NODE_ENV === 'production' && 'serviceWorker' in navigator) {\r\n        const publicUrl = new URL(process.env.PUBLIC_URL, window.location.href);\r\n        if (publicUrl.origin !== window.location.origin) return;\r\n\r\n        window.addEventListener('load', () => {\r\n            const swUrl = `${process.env.PUBLIC_URL}/service-worker.js`;\r\n\r\n            if (isLocalhost) {\r\n                checkValidServiceWorker(swUrl, config);\r\n                navigator.serviceWorker.ready.then(() => {\r\n                    console.log('PWA: This web app is being served cache-first by a service worker.');\r\n      